draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // couple
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20*Math.sin(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20*Math.sin(t), H/2, 10, 0, 2*Math.PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2, 10, 0, 2*Math.PI);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 20*Math.sin(t), H/2);
  ctx.lineTo(W/2 + 50 + 20*Math.cos(t), H/2);
  ctx.stroke();

  // old car
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 30, H - 50, 60, 20);
  ctx.fillRect(W/2 - 40, H - 70, 10, 20);
  ctx.fillRect(W/2 + 30, H - 70, 10, 20);

  ctx.restore();
}
